urlset:
{%- for file in pages -%}
    {% if not file.page.is_link and (file.page.abs_url or file.page.canonical_url) %}
    {%- set u = file.page.url -%}
    {# SEO: exclude noindexed thin pages (blog categories, archives, tag index,
       paginated pages) so the sitemap only advertises real, indexable content. #}
    {%- if not ('category/' in u or 'archive/' in u or '/page/' in u or u.rstrip('/') == 'tags') -%}

         {% if file.page.canonical_url %}{{ file.page.canonical_url|e }}{% else %}{{ file.page.abs_url|e }}{% endif %}
         {% if file.page.update_date %}{{file.page.update_date}}{% endif %}

    {%- endif -%}
    {%- endif -%}
{% endfor %}
